package main
import (
    "fmt"
    "go/scanner"
    "go/token"
)
func count(src string) int {
    fset := token.NewFileSet()
    file := fset.AddFile("a.go", -1, len(src))
    var s scanner.Scanner
    s.Init(file, []byte(src), nil, 0)
    cnt:=0
    for{
        _, tok,_ := s.Scan()
        if tok==token.EOF {break}
        if tok==token.SEMICOLON {continue}
        // maybe dupl excludes PACKAGE and IMPORT? Let's see
        // Try various filters
        cnt++
    }
    return cnt
}
func main(){
    // Two identical files with 8 assignments each + func header
    src := "package p\nfunc f(){\nx:=1+2\ny:=3+4\nz:=5+6\na:=7+8\nb:=9+10\nc:=11+12\nd:=13+14\ne:=15+16\n}\n"
    fmt.Println("cnt src", count(src)) // 48
    // But clone reported at t=46 still clones, 48 -2 =46? Maybe package tokens are 2 (package p) excluded?
    srcB := "package p\nfunc g(){\nx:=1+2\ny:=3+4\nz:=5+6\na:=7+8\nb:=9+10\nc:=11+12\nd:=13+14\ne:=15+16\n}\n"
    fmt.Println("cnt srcB", count(srcB))

    // Try count without package: remove first 2 tokens package p
    src2 := "func f(){\nx:=1+2\ny:=3+4\nz:=5+6\na:=7+8\nb:=9+10\nc:=11+12\nd:=13+14\ne:=15+16\n}\n"
    fmt.Println("cnt without pkg", count(src2)) // 46? Let's see
    // 48 -2 =46 yes
    src3 := "func g(){\nx:=1+2\ny:=3+4\nz:=5+6\na:=7+8\nb:=9+10\nc:=11+12\nd:=13+14\ne:=15+16\n}\n"
    fmt.Println("cnt without pkg", count(src3))

    // So maybe dupl includes everything but our count without package gives 46 which matches threshold boundary.
    // Let's test more: file with package p plus simple func x:=1 (11 tokens without semi). But clone at t=9 clones, at 10 not. So 11 -2 =9 -> 9 is threshold max.
    // That matches: full file tokens without package =9? Let's see: func f(){x:=1} tokens without package p = 11 -2 =9 indeed. And threshold 9 clones, 10 not. So package excluded?
    src4 := "package p\nfunc f(){x:=1}\n"
    fmt.Println("cnt src4", count(src4), "cnt no pkg", count("func f(){x:=1}\n"))
    // For file with x:=1,y:=2 (two statements) total 14 without semi, 14-2=12 -> threshold max was 12 clones, 13 not. Yes matches.
    src5 := "package p\nfunc f(){\nx:=1\ny:=2\n}\n"
    fmt.Println("cnt src5", count(src5), "no pkg", count("func f(){\nx:=1\ny:=2\n}\n"))
}
