    s.Init(file, []byte(src), nil, 0)
    var toks []token.Token
    for{
        _, tok,_ := s.Scan()
        if tok==token.EOF {break}
        if tok==token.SEMICOLON {continue}
        toks = append(toks, tok)
    }
    return toks
}
func main(){
    // check package vs different package: package p vs package q difference only in IDENT value, but IDENT normalized should be same, yet earlier diff package still allowed clone? But our mapping shows IDENT normalized, so package p vs q would still be same token sequence (IDENT vs IDENT same). So package line would be identical after normalization, but maybe dupl skips package clause entirely?
    // Let's test with different package but same func: threshold 46 boundary we saw with same package. Test diff package with same content.

    // Instead let's observe: files a.go package p vs b.go package q had same clone behavior as same package (both had max 6 for empty func). So package difference didn't affect clone length threshold? That suggests package tokens not counted.
