    // count = ? Let's compute
    a := "package p\nfunc foo(){}\n"
    b := "package q\nfunc bar(){}\n"
    fmt.Println("a", tokens(a))
    fmt.Println("b", tokens(b))
    fmt.Printf("len a %d b %d\n", len(tokens(a)), len(tokens(b)))
    // Without package: func foo(){}
    fa := "func foo(){}\n"
    fb := "func bar(){}\n"
    fmt.Println("fa", tokens(fa))
    fmt.Println("fb", tokens(fb))
    fmt.Printf("len fa %d fb %d\n", len(tokens(fa)), len(tokens(fb)))

    // If package included, empty func would have tokens: package, IDENT, func, IDENT, (, ), {, } => 8 tokens
    // Without package: func, IDENT, (, ), {, } => 6 tokens
    // Our earlier observed max threshold for empty func was 6, not 8. So indeed package excluded. Good.

