package main
import (
    "fmt"
    "go/token"
    "go/scanner"
    "os"
    "path/filepath"
)
func main(){
    if len(os.Args)<2{fmt.Println("need path");return}
    path:=os.Args[1]
    src, _:=os.ReadFile(path)
    fset := token.NewFileSet()
    file := fset.AddFile(path, -1, len(src))
    var s scanner.Scanner
    s.Init(file, src, nil, scanner.ScanComments)
    for{
        pos, tok, lit := s.Scan()
        if tok==token.EOF {break}
        fmt.Printf("%s %v %q\n", fset.Position(pos), tok, lit)
    }
    // also list files recursively
    _ = filepath.Walk
}
