// Token normalization
type NormToken int

const (
    NT_IDENT NormToken = iota
    NT_LITERAL
    NT_OPERATOR
    NT_ASSIGN
    NT_INCDEC
    NT_ARROW
    NT_ELLIPSIS
    NT_PERIOD
    NT_COMMA
    NT_COLON
    NT_SEMICOLON // not used
    NT_LPAREN
    NT_RPAREN
    NT_LBRACK
    NT_RBRACK
    NT_LBRACE
    NT_RBRACE
    // keywords each distinct, start from 100
    NT_KEYWORD_BASE = 100
)

func normalize(tok token.Token) NormToken {
    switch tok {
    case token.IDENT:
        return NT_IDENT
    case token.INT, token.FLOAT, token.IMAG, token.CHAR, token.STRING:
        return NT_LITERAL
    // Operators bucket
    case token.ADD, token.SUB, token.MUL, token.QUO, token.REM,
         token.AND, token.OR, token.XOR, token.SHL, token.SHR, token.AND_NOT,
         token.LAND, token.LOR,
         token.EQL, token.NEQ, token.LSS, token.GTR, token.LEQ, token.GEQ,
         token.NOT:
        return NT_OPERATOR
    case token.DEFINE, token.ASSIGN,
         token.ADD_ASSIGN, token.SUB_ASSIGN, token.MUL_ASSIGN, token.QUO_ASSIGN, token.REM_ASSIGN,
         token.AND_ASSIGN, token.OR_ASSIGN, token.XOR_ASSIGN, token.SHL_ASSIGN, token.SHR_ASSIGN, token.AND_NOT_ASSIGN:
        return NT_ASSIGN
    case token.INC, token.DEC:
        return NT_INCDEC
    case token.ARROW:
        return NT_ARROW
    case token.ELLIPSIS:
        return NT_ELLIPSIS
    case token.PERIOD:
        return NT_PERIOD
    case token.COMMA:
        return NT_COMMA
    case token.COLON:
        return NT_COLON
    case token.LPAREN:
        return NT_LPAREN
    case token.RPAREN:
        return NT_RPAREN
    case token.LBRACK:
        return NT_LBRACK
    case token.RBRACK:
        return NT_RBRACK
    case token.LBRACE:
        return NT_LBRACE
    case token.RBRACE:
        return NT_RBRACE
    case token.SEMICOLON:
        return NT_SEMICOLON
    default:
        if tok.IsKeyword() {
            // distinct for each keyword
            return NT_KEYWORD_BASE + NormToken(tok)
        }
        // fallback distinct
        return NormToken(int(tok) + 500)
    }
}

