func isVendor(path string) bool {
    // check if any component is "vendor"
    parts := strings.Split(filepath.ToSlash(path), "/")
    for _, p := range parts {
        if p == "vendor" {
            return true
        }
    }
    return false
}

func isVendorDir(path string) bool {
    base := filepath.Base(path)
    return base == "vendor"
}

