package main

import (
    "bufio"
    "flag"
    "fmt"
    "go/parser"
    "go/scanner"
    "go/token"
    "html"
    "log"
    "os"
    "path/filepath"
    "sort"
    "strings"
)

var (
    flagFiles bool
    flagHTML bool
    flagPlumbing bool
    flagThreshold int
    flagVendor bool
    flagVerbose bool
)

func init() {
    flag.BoolVar(&flagFiles, "files", false, "read file names from stdin one at each line")
    flag.BoolVar(&flagHTML, "html", false, "output the results as HTML, including duplicate code fragments")
    flag.BoolVar(&flagPlumbing, "plumbing", false, "plumbing (easy-to-parse) output for consumption by scripts or tools")
    flag.IntVar(&flagThreshold, "t", 15, "minimum token sequence size as a clone")
    flag.IntVar(&flagThreshold, "threshold", 15, "minimum token sequence size as a clone")
    flag.BoolVar(&flagVendor, "vendor", false, "check files in vendor directory")
    flag.BoolVar(&flagVerbose, "v", false, "explain what is being done")
    flag.BoolVar(&flagVerbose, "verbose", false, "explain what is being done")
}

func printUsage() {
    fmt.Fprintf(os.Stderr, "Usage: dupl [flags] [paths]\n\n")
    fmt.Fprintf(os.Stderr, "Paths:\n")
    fmt.Fprintf(os.Stderr, "  If the given path is a file, dupl will use it regardless of\n")
    fmt.Fprintf(os.Stderr, "  the file extension. If it is a directory, it will recursively\n")
    fmt.Fprintf(os.Stderr, "  search for *.go files in that directory.\n\n")
    fmt.Fprintf(os.Stderr, "  If no path is given, dupl will recursively search for *.go\n")
    fmt.Fprintf(os.Stderr, "  files in the current directory.\n\n")
    fmt.Fprintf(os.Stderr, "Flags:\n")
    fmt.Fprintf(os.Stderr, "  -files\n")
    fmt.Fprintf(os.Stderr, "    \tread file names from stdin one at each line\n")
    fmt.Fprintf(os.Stderr, "  -html\n")
    fmt.Fprintf(os.Stderr, "    \toutput the results as HTML, including duplicate code fragments\n")
    fmt.Fprintf(os.Stderr, "  -plumbing\n")
    fmt.Fprintf(os.Stderr, "    \tplumbing (easy-to-parse) output for consumption by scripts or tools\n")
    fmt.Fprintf(os.Stderr, "  -t, -threshold size\n")
    fmt.Fprintf(os.Stderr, "    \tminimum token sequence size as a clone (default 15)\n")
    fmt.Fprintf(os.Stderr, "  -vendor\n")
    fmt.Fprintf(os.Stderr, "    \tcheck files in vendor directory\n")
    fmt.Fprintf(os.Stderr, "  -v, -verbose\n")
    fmt.Fprintf(os.Stderr, "    \texplain what is being done\n")
    fmt.Fprintf(os.Stderr, "\nExamples:\n")
    fmt.Fprintf(os.Stderr, "  dupl -t 100\n")
    fmt.Fprintf(os.Stderr, "    \tSearch clones in the current directory of size at least\n")
    fmt.Fprintf(os.Stderr, "    \t100 tokens.\n")
    fmt.Fprintf(os.Stderr, "  dupl $(find app/ -name '*_test.go')\n")
    fmt.Fprintf(os.Stderr, "    \tSearch for clones in tests in the app directory.\n")
    fmt.Fprintf(os.Stderr, "  find app/ -name '*_test.go' |dupl -files\n")
    fmt.Fprintf(os.Stderr, "    \tThe same as above.\n")
}

func normalize(tok token.Token) string {
    switch tok {
    case token.IDENT:
        return "I"
    case token.INT, token.FLOAT, token.IMAG, token.CHAR, token.STRING:
        return "L"
    case token.ADD, token.SUB, token.MUL, token.QUO, token.REM,
        token.AND, token.OR, token.XOR, token.SHL, token.SHR, token.AND_NOT,
        token.LAND, token.LOR,
        token.EQL, token.NEQ, token.LSS, token.GTR, token.LEQ, token.GEQ,
        token.NOT, token.TILDE:
        return "O"
    case token.DEFINE, token.ASSIGN,
        token.ADD_ASSIGN, token.SUB_ASSIGN, token.MUL_ASSIGN, token.QUO_ASSIGN, token.REM_ASSIGN,
        token.AND_ASSIGN, token.OR_ASSIGN, token.XOR_ASSIGN, token.SHL_ASSIGN, token.SHR_ASSIGN, token.AND_NOT_ASSIGN:
        return "A"
    case token.INC, token.DEC:
        return "D"
    case token.ARROW:
        return "R"
    case token.ELLIPSIS:
        return "E"
    case token.PERIOD:
        return "."
    case token.COMMA:
        return ","
    case token.COLON:
        return ":"
    case token.LPAREN:
        return "("
    case token.RPAREN:
        return ")"
    case token.LBRACK:
        return "["
    case token.RBRACK:
        return "]"
    case token.LBRACE:
        return "{"
    case token.RBRACE:
        return "}"
    case token.SEMICOLON:
        return ";"
    default:
        if tok.IsKeyword() {
            return "K_" + tok.String()
        }
        return tok.String()
    }
}

type File struct {
    Path string
    Tokens []string
    Lines []int
    RawLines []string
    Content string
}

type Clone struct {
    FileIdx int
    Start int
    End int
    StartLine int
    EndLine int
}

type Group struct {
    Clones []Clone
    Len int
    TokenSeq string
}

func isVendor(path string) bool {
    parts := strings.Split(filepath.ToSlash(path), "/")
    for _, p := range parts {
        if p == "vendor" {
            return true
        }
    }
    return false
}

func isVendorDir(path string) bool {
    return filepath.Base(path) == "vendor"
}

func parseFile(path string) (*File, error) {
    data, err := os.ReadFile(path)
    if err != nil {
        return nil, err
    }
    content := string(data)
    rawLines := strings.Split(content, "\n")

    fset := token.NewFileSet()
    file := fset.AddFile(path, -1, len(data))
    // need error handler to log parser errors like original
    // Use parser.ParseFile for errors
    // But we also need tokens
    // Use scanner with error handler
    var scanErrors []string
    errorHandler := func(pos token.Position, msg string) {
        // Scanner errors: pos already includes file
        scanErrors = append(scanErrors, fmt.Sprintf("%s: %s", pos, msg))
    }
    var s scanner.Scanner
    s.Init(file, data, errorHandler, scanner.ScanComments)
    var tokens []string
    var lines []int
    var allRaw []token.Token
    var allLines []int
    for {
        pos, tok, _ := s.Scan()
        if tok == token.EOF {
            break
        }
        if tok == token.COMMENT {
            continue
        }
        if tok == token.SEMICOLON {
            continue
        }
        allRaw = append(allRaw, tok)
        allLines = append(allLines, fset.Position(pos).Line)
        tokens = append(tokens, normalize(tok))
        lines = append(lines, fset.Position(pos).Line)
    }
    for _, e := range scanErrors {
        log.Println(e)
    }
    // Also try parser for syntax errors (like expected IDENT)
    fset2 := token.NewFileSet()
    _, perr := parser.ParseFile(fset2, path, data, parser.AllErrors)
    if perr != nil {
        // perr may be scanner.ErrorList
        // It is already logged via scanner? But parser errors include more
        // The error string may contain multiple lines like "path:line:col: msg"
        // We need to log each error via log.Println
        // The perr's Error() returns string with newlines
        msg := perr.Error()
        for _, line := range strings.Split(msg, "\n") {
            if line != "" {
                log.Println(line)
            }
        }
        // Even if parse error, we still keep tokens we scanned? Original still continues but reports Found total 0? Let's check: earlier bad.go with syntax error gave Found total 0, but still logged error and returned 0 groups.
        // Should we return file with tokens or not? Original still considered file but found 0 clones because parsing errors maybe cause tokens to be incomplete? However it still processed other files? In earlier test with one bad.go and one good file, it gave 0 clones total, not clones for good file alone. So when file has syntax error, maybe it's excluded from clone detection? Let's see: /tmp/empty_test had bad.go and good file? In earlier test, /tmp/empty_test with bad.go gave 0 groups, not clones for other files. That suggests bad file causes overall 0 clones? Or maybe because good file was foo.txt not .go? Let's test more: create directory with bad.go and good pair that would otherwise clone.
        // For now, we will keep tokens even if parse error, but ensure we log.
    }

    // Strip package clause: first two tokens if K_package
    if len(tokens) >=2 && tokens[0] == "K_package" {
        tokens = tokens[2:]
        lines = lines[2:]
        // Also need to adjust rawLines? Not needed
    }

    return &File{Path: path, Tokens: tokens, Lines: lines, RawLines: rawLines, Content: content}, nil
}

func buildFileList() []string {
    var filePaths []string
    if flagFiles {
        scanner := bufio.NewScanner(os.Stdin)
        for scanner.Scan() {
            line := scanner.Text()
            if line == "" {
                continue
            }
            filePaths = append(filePaths, line)
        }
        if err := scanner.Err(); err != nil {
            log.Println(err)
        }
    } else {
        args := flag.Args()
        if len(args) == 0 {
            filePaths = append(filePaths, ".")
        } else {
            filePaths = append(filePaths, args...)
        }
    }

    var files []string
    if flagFiles {
        for _, p := range filePaths {
            info, err := os.Stat(p)
            if err != nil {
                log.Printf("open %s: no such file or directory", p)
                continue
            }
            if info.IsDir() {
                log.Printf("read %s: is a directory", p)
                continue
            }
            if !flagVendor && isVendor(p) {
                continue
            }
            files = append(files, p)
        }
    } else {
        for _, p := range filePaths {
            info, err := os.Lstat(p)
            if err != nil {
                log.Printf("lstat %s: no such file or directory", p)
                os.Exit(1)
            }
            if info.IsDir() {
                filepath.Walk(p, func(path string, info os.FileInfo, err error) error {
                    if err != nil {
                        return nil
                    }
                    if info.IsDir() {
                        if !flagVendor && isVendorDir(path) {
                            return filepath.SkipDir
                        }
                        return nil
                    }
                    if strings.HasSuffix(path, ".go") {
                        if !flagVendor && isVendor(path) {
                            return nil
                        }
                        files = append(files, path)
                    }
                    return nil
                })
            } else {
                files = append(files, p)
            }
        }
    }
    sort.Strings(files)
    return files
}

