func buildFileList() []string {
    var filePaths []string
    if flagFiles {
        scanner := bufio.NewScanner(os.Stdin)
        for scanner.Scan() {
            line := scanner.Text()
            if line == "" {
                continue
            }
            filePaths = append(filePaths, line)
        }
        if err := scanner.Err(); err != nil {
            log.Println(err)
        }
    } else {
        args := flag.Args()
        if len(args) == 0 {
            filePaths = append(filePaths, ".")
        } else {
            filePaths = append(filePaths, args...)
        }
    }

    var files []string
    if flagFiles {
        for _, p := range filePaths {
            info, err := os.Stat(p)
            if err != nil {
                log.Printf("open %s: no such file or directory", p)
                continue
            }
            if info.IsDir() {
                log.Printf("read %s: is a directory", p)
                continue
            }
            if !flagVendor && isVendor(p) {
                continue
            }
            files = append(files, p)
        }
    } else {
        for _, p := range filePaths {
            info, err := os.Lstat(p)
            if err != nil {
                log.Printf("lstat %s: no such file or directory", p)
                os.Exit(1)
            }
            if info.IsDir() {
                filepath.Walk(p, func(path string, info os.FileInfo, err error) error {
                    if err != nil {
                        return nil
                    }
                    if info.IsDir() {
                        if !flagVendor && isVendorDir(path) {
                            return filepath.SkipDir
                        }
                        return nil
                    }
                    if strings.HasSuffix(path, ".go") {
                        if !flagVendor && isVendor(path) {
                            return nil
                        }
                        files = append(files, path)
                    }
                    return nil
                })
            } else {
                files = append(files, p)
            }
        }
    }
    sort.Strings(files)
    return files
}

