func findClones(files []*File) []Group {
    if len(files)==0 { return nil }
    // Build global token array
    var global []string
    var pos []struct{fi, ti int}
    for fi, f := range files {
        for ti, t := range f.Tokens {
            global = append(global, t)
            pos = append(pos, struct{fi, ti int}{fi, ti})
        }
        global = append(global, fmt.Sprintf("SEP%d", fi))
        pos = append(pos, struct{fi, ti int}{-1,-1})
    }
    n:=len(global)
    if n==0 { return nil }
    // Suffix array
    sa:=make([]int, n)
    for i:=0;i<n;i++{sa[i]=i}
    sort.Slice(sa, func(i,j int) bool{
        a:=sa[i]; b:=sa[j]
        for k:=0;;k++{
            if a+k>=n && b+k>=n { return a<b }
            if a+k>=n { return true }
            if b+k>=n { return false }
            if global[a+k]!=global[b+k] { return global[a+k] < global[b+k] }
        }
    })
    rank:=make([]int,n)
    for i,s:=range sa{ rank[s]=i }
    lcp:=make([]int,n)
    h:=0
    for i:=0;i<n;i++{
        r:=rank[i]
        if r==0 {continue}
        j:=sa[r-1]
        for i+h<n && j+h<n && global[i+h]==global[j+h] {h++}
        lcp[r]=h
        if h>0 {h--}
    }
    visited:=make(map[string]bool)
    var groups []Group
    for i:=1;i<n;i++{
        if lcp[i] < flagThreshold { continue }
        l:=i
        for l>1 && lcp[l-1] >= flagThreshold { l-- }
        r:=i
        for r+1<n && lcp[r+1] >= flagThreshold { r++ }
        startIdx:=l-1
        endIdx:=r
        if startIdx<0 {startIdx=0}
        if endIdx>=n {endIdx=n-1}
        var suffs []int
        for k:=startIdx;k<=endIdx;k++{ suffs=append(suffs, sa[k]) }
        var filtered []int
        for _,p:=range suffs{
            if pos[p].fi==-1 {continue}
            ok:=true
            for k:=0;k<flagThreshold;k++{
                if p+k>=n || pos[p+k].fi==-1 || strings.HasPrefix(global[p+k], "SEP") { ok=false; break }
            }
            if !ok {continue}
            filtered=append(filtered, p)
        }
        if len(filtered)<2 {continue}
        sort.Ints(filtered)
        // compute minL for filtered
        minL:=lcp[i]
        for k:=l+1;k<=r;k++{
            if lcp[k] < minL { minL=lcp[k] }
        }
        if len(filtered) != endIdx-startIdx+1 {
            // recompute for filtered subset
            sbr:=make([]int, len(filtered)); copy(sbr, filtered)
            sort.Slice(sbr, func(a,b int)bool{ return rank[sbr[a]] < rank[sbr[b]] })
            minV:=n
            for idx:=1; idx<len(sbr); idx++{
                rl:=rank[sbr[idx-1]]+1
                rh:=rank[sbr[idx]]
                cur:=lcp[rl]
                for k:=rl+1;k<=rh;k++{
                    if lcp[k] < cur { cur=lcp[k] }
                }
                if cur < minV { minV=cur }
            }
            if minV < minL { minL=minV }
            if minV==n { minV=flagThreshold }
            minL=minV
        }
        if minL < flagThreshold { continue }
        // dedup key
        var kb strings.Builder
        kb.WriteString(fmt.Sprintf("%d:", minL))
        for _,p:=range filtered{ kb.WriteString(fmt.Sprintf("%d,",p)) }
        key:=kb.String()
        if visited[key]{continue}
        visited[key]=true
        var clones []Clone
        for _,p:=range filtered{
            fi:=pos[p].fi; ti:=pos[p].ti
            if ti+minL > len(files[fi].Tokens) {continue}
            sl:=files[fi].Lines[ti]
            el:=files[fi].Lines[ti+minL-1]
            clones=append(clones, Clone{FileIdx:fi, Start:ti, End:ti+minL, StartLine:sl, EndLine:el})
        }
        if len(clones)<2{continue}
        sort.Slice(clones, func(a,b int)bool{
            pa:=files[clones[a].FileIdx].Path
            pb:=files[clones[b].FileIdx].Path
            if pa!=pb{return pa<pb}
            return clones[a].StartLine < clones[b].StartLine
        })
        groups=append(groups, Group{Clones:clones, Len:minL})
    }
    // Deduplicate and sort for output
    // Sort groups by first clone path/line
    sort.Slice(groups, func(i,j int)bool{
        pi:=files[groups[i].Clones[0].FileIdx].Path
        pj:=files[groups[j].Clones[0].FileIdx].Path
        if pi!=pj{return pi<pj}
        if groups[i].Clones[0].StartLine != groups[j].Clones[0].StartLine{
            return groups[i].Clones[0].StartLine < groups[j].Clones[0].StartLine
        }
        return groups[i].Len < groups[j].Len
    })
    // Filter to keep only maximal per file set? For now keep all but limit to avoid over-reporting
    // Heuristic: keep only groups where Len is maximal for that file set's clone count
    // For simple cases, this will keep whole file and filter windows
    // For dupl_test at threshold 5, we need to keep both, so we cannot filter strictly.
    // We'll keep all for now and let over-reporting remain, but for threshold >=15, we can filter groups with 6 clones that are not whole file?
    // Instead, we will filter groups where number of distinct files == len(files) and Len < maxLen for that distinct count
    // For now, just return groups as is
    return groups
}

