func isVendor(path string) bool {
    parts := strings.Split(filepath.ToSlash(path), "/")
    for _, p := range parts {
        if p == "vendor" {
            return true
        }
    }
    return false
}
func isVendorDir(p string) bool { return filepath.Base(p) == "vendor" }

func parseFile(path string) (*File, error) {
    data, err := os.ReadFile(path)
    if err != nil { return nil, err }
    content := string(data)
    rawLines := strings.Split(content, "\n")
    fset := token.NewFileSet()
    file := fset.AddFile(path, -1, len(data))
    var s scanner.Scanner
    // Use error handler to log scanner errors
    var errs []string
    eh := func(pos token.Position, msg string) {
        errs = append(errs, fmt.Sprintf("%s: %s", pos, msg))
    }
    s.Init(file, data, eh, scanner.ScanComments)
    var toks []string
    var lines []int
    for {
        pos, tok, _ := s.Scan()
        if tok == token.EOF { break }
        if tok == token.COMMENT { continue }
        if tok == token.SEMICOLON { continue }
        toks = append(toks, normalize(tok))
        lines = append(lines, fset.Position(pos).Line)
    }
    for _, e := range errs {
        log.Println(e)
    }
    if len(toks) >= 2 && toks[0] == "K_package" {
        toks = toks[2:]
        lines = lines[2:]
    }
    return &File{Path: path, Tokens: toks, Lines: lines, RawLines: rawLines}, nil
}

