    fmt.Println("<!DOCTYPE html>")
    fmt.Println("<meta charset=\"utf-8\"/>")
    fmt.Println("<title>Duplicates</title>")
    fmt.Println("<style>")
    fmt.Println("\tpre {")
    fmt.Println("\t\tbackground-color: #FFD;")
    fmt.Println("\t\tborder: 1px solid #E2E2E2;")
    fmt.Println("\t\tpadding: 1ex;")
    fmt.Println("\t}")
    fmt.Println("</style>")
    if len(groups)==0 {return}
    for idx,g:=range groups{
        fmt.Printf("<h1>#%d found %d clones</h1>\n", idx+1, len(g.Clones))
        for _,c:=range g.Clones{
            f:=files[c.FileIdx]
            fmt.Printf("<h2>%s:%d</h2>\n", f.Path, c.StartLine)
            start:=c.StartLine-1
            end:=c.EndLine
            if start<0{start=0}
            if end>len(f.RawLines){end=len(f.RawLines)}
            frag:=strings.Join(f.RawLines[start:end], "\n")
            esc:=html.EscapeString(frag)
            fmt.Printf("<pre>%s</pre>\n", esc)
        }
    }
}

func main(){
    flag.Usage=printUsage
    flag.Parse()
    if flagHTML && flagPlumbing{
        log.Println("you can have either plumbing or HTML output")
        fmt.Println("Found total 0 clone groups.")
        return
    }
    flist:=buildFileList()
    if flagVerbose{ log.Println("Building suffix tree") }
    var files []*File
    for _,p:=range flist{
        f,err:=parseFile(p)
        if err!=nil{ log.Printf("open %s: %v", p, err); continue }
        files=append(files, f)
    }
    if flagVerbose{ log.Println("Searching for clones") }
    groups:=findClones(files)
    if flagHTML{ printHTML(groups, files); return }
    if flagPlumbing{
        for _,g:=range groups{
            n:=len(g.Clones)
            for i:=0;i<n;i++{
                cur:=g.Clones[i]
                nxt:=g.Clones[(i+1)%n]
                fmt.Printf("%s:%d-%d: duplicate of %s:%d-%d\n", files[cur.FileIdx].Path, cur.StartLine, cur.EndLine, files[nxt.FileIdx].Path, nxt.StartLine, nxt.EndLine)
            }
        }
        return
    }
    for _,g:=range groups{
        fmt.Printf("found %d clones:\n", len(g.Clones))
        for _,c:=range g.Clones{
            fmt.Printf("  %s:%d,%d\n", files[c.FileIdx].Path, c.StartLine, c.EndLine)
        }
        fmt.Println()
    }
    fmt.Printf("Found total %d clone groups.\n", len(groups))
}
